import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey, type Claim } from '../claims/claims';
import { GRADES, peopleKey, useEditingPerson, usePeople, useShowRetired, type Person } from './people';

/** The form's values. `gradeFrom` (yyyy-MM-dd) is the date the grade is given from; blank, the sheet's today. A
 *  person's first grade applies from the beginning of time. */
type Values = { name: string; grade: string; gradeFrom: string };
const EMPTY: Values = { name: '', grade: 'A', gradeFrom: '' };

type Quick = { name: string; amount: string };
const NO_QUICK: Quick = { name: '', amount: '' };

/** The quick-add bar: a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person with the
 *  name (case and outer spaces ignored); a name not on the sheet adds the person, grade A, first. The server does it as
 *  one change, so a refused claim adds no person. */
function QuickAdd({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [values, setValues] = useState<Quick>(NO_QUICK);
  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (v: Quick) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, { ...v, by: user }),
    onSuccess: () => {
      setValues(NO_QUICK);
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const change = (v: Partial<Quick>) => {
    setValues((was) => ({ ...was, ...v }));
    add.reset();
  };

  return (
    <form
      data-testid="quick-add"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        add.reset();
        add.mutate(values);
      }}
    >
      Quick add{' '}
      <input data-testid="quick-name" placeholder="Name" value={values.name} onChange={(e) => change({ name: e.target.value })} />{' '}
      <input
        data-testid="quick-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={values.amount}
        onChange={(e) => change({ amount: e.target.value })}
      />{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add draft claim
      </button>
      {add.isError && (
        <span data-testid="quick-error">
          {' '}
          {values.name.trim() === ''
            ? 'A name is required.'
            : "The amount must be 0.00 or more, with up to two decimals, today not inside a closed period, and not after the person's retirement date."}
        </span>
      )}
    </form>
  );
}

/** The sheet's people: a form that adds a person or saves the one being edited, and the list. The editor
 *  remembers the version of the person it loaded; a save refused because someone else saved the person since
 *  (412) shows the error and puts the current values, and their version, in the form. */
function People({ sheetId, user }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId);
  const [showRetired, setShowRetired] = useShowRetired();
  const queryClient = useQueryClient();
  const [editingId, setEditingId] = useEditingPerson();
  const editing = people.data?.find((p) => String(p.id) === editingId);
  const [values, setValues] = useState<Values>(EMPTY);
  const [version, setVersion] = useState<number | undefined>(undefined);
  const submit = useSubmitOnce();

  const save = useMutation({
    mutationFn: ({ id, ...v }: Values & { id?: number; version?: number }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      const body = { ...v, by: user };
      return id === undefined ? postJson<Person>(base, body) : putJson<Person>(`${base}/${id}`, body);
    },
    onSuccess: () => {
      setValues(EMPTY);
      setEditingId(undefined);
      setVersion(undefined);
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: async (error, { id }) => {
      if (id === undefined || !(error instanceof HttpError) || error.status !== 412) return;
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      const now = queryClient.getQueryData<Person[]>(peopleKey(sheetId))?.find((p) => p.id === id);
      if (now) {
        setValues({ name: now.name, grade: now.grade, gradeFrom: '' });
        setVersion(now.version);
      }
    },
    onSettled: submit.end,
  });

  const change = (v: Partial<Values>) => {
    setValues((was) => ({ ...was, ...v }));
    save.reset();
  };
  const openEditor = (p: Person) => {
    save.reset();
    setValues({ name: p.name, grade: p.grade, gradeFrom: '' });
    setVersion(p.version);
    setEditingId(String(p.id));
  };
  const cancel = () => {
    save.reset();
    setValues(EMPTY);
    setVersion(undefined);
    setEditingId(undefined);
  };

  return (
    <section data-testid="people">
      <h3>People</h3>
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          save.mutate(editing ? { ...values, id: editing.id, version } : values);
        }}
      >
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={values.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select data-testid="person-form-grade" value={values.grade} onChange={(e) => change({ grade: e.target.value })}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder="yyyy-mm-dd"
            value={values.gradeFrom}
            onChange={(e) => change({ gradeFrom: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing ? 'Save' : 'Add person'}
        </button>
        {editing && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error">
            {values.name.trim() === ''
              ? 'A name is required.'
              : save.error instanceof HttpError && save.error.status === 409
                ? 'That name is already in use on this sheet.'
                : save.error instanceof HttpError && save.error.status === 412
                  ? 'Someone else saved this person since you opened it; the form now shows their values.'
                  : 'Could not save this person.'}
          </span>
        )}
      </form>
      <QuickAdd sheetId={sheetId} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      {people.isError && <p data-testid="people-load-error">Could not load people.</p>}
      <table data-testid="people-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PeopleHead.Slot sheetId={sheetId} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {people.data?.filter((p) => showRetired || p.retiredFrom === null).map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonRow.Slot sheetId={sheetId} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => openEditor(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 10, Component: People });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { live, useClaims } from '../claims/claims';
import { gradeOn, usePeople } from '../people/people';
import { claimDue, rateFor, sum, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { periodsKey, usePeriods, type Period } from './periods';

type Values = { name: string; from: string; to: string };
const EMPTY: Values = { name: '', from: '', to: '' };

/** The sheet's periods: the form that adds one, and each period with its due-total — the figures of the claims
 *  that count, each with its late charge (a held person's OPEN claims do not) whose date falls in it, added up (skipping n/a); a closed period
 *  shows the due-total fixed when it was closed. */
function Periods({ sheetId, user }: { sheetId: string; user: string }) {
  const periods = usePeriods(sheetId);
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const queryClient = useQueryClient();
  const [values, setValues] = useState<Values>(EMPTY);

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: (v: Values) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, { ...v, by: user }),
    onSuccess: () => {
      setValues(EMPTY);
      void queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const change = (v: Partial<Values>) => {
    setValues((was) => ({ ...was, ...v }));
    save.reset();
  };

  const dueTotal = (p: Period) => {
    const byId = new Map((people.data ?? []).map((person) => [person.id, person]));
    const inPeriod = live(claims.data ?? [], people.data).filter((c) => p.from <= c.date && c.date <= p.to);
    return sum(
      inPeriod.map((c) => {
        const person = byId.get(c.personId);
        return claimDue(c, person === undefined ? undefined : rateFor(rates.data, gradeOn(person, c.date), c.date), floor, late);
      }),
    );
  };

  return (
    <section data-testid="periods">
      <h3>Periods</h3>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          save.mutate(values);
        }}
      >
        <input data-testid="period-form-name" placeholder="Name" value={values.name} onChange={(e) => change({ name: e.target.value })} />{' '}
        <label>
          From <input type="date" data-testid="period-form-from" value={values.from} onChange={(e) => change({ from: e.target.value })} />
        </label>{' '}
        <label>
          To <input type="date" data-testid="period-form-to" value={values.to} onChange={(e) => change({ to: e.target.value })} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && (
          <span data-testid="period-form-error">
            A period needs a name not already on the sheet, and dates from on or before to that overlap no other period.
          </span>
        )}
      </form>
      {periods.isError && <p data-testid="periods-load-error">Could not load periods.</p>}
      <table data-testid="periods-table">
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{p.closed && p.closedTotal !== null ? p.closedTotal : dueTotal(p)}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <PeriodClose sheetId={sheetId} user={user} period={p} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 7, Component: Periods });

/** Closes a period: its due-total is fixed as it is now. Reopens a closed one (a steward only): its due-total is
 *  live again. A refused action shows the period's error; the next action on the period clears it. */
function PeriodClose({ sheetId, user, period }: { sheetId: string; user: string; period: Period }) {
  const queryClient = useQueryClient();
  const act = (action: 'close' | 'reopen') =>
    postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/${period.id}/${action}`, { by: user });
  const onSuccess = () => {
    void queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
  };
  const close = useMutation({ mutationFn: () => act('close'), onSuccess });
  const reopen = useMutation({ mutationFn: () => act('reopen'), onSuccess });
  const pending = close.isPending || reopen.isPending;
  return (
    <>
      <button
        type="button"
        data-testid="period-close"
        disabled={pending}
        onClick={() => {
          close.reset();
          reopen.reset();
          close.mutate();
        }}
      >
        Close
      </button>{' '}
      <button
        type="button"
        data-testid="period-reopen"
        disabled={pending}
        onClick={() => {
          close.reset();
          reopen.reset();
          reopen.mutate();
        }}
      >
        Reopen
      </button>
      {close.isError && <span data-testid="period-error"> This period is already closed.</span>}
      {reopen.isError && <span data-testid="period-error"> Only a steward can reopen a period, and only a closed one.</span>}
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A period of the sheet: `name` is unique on the sheet (case ignored); `from` and `to` (yyyy-MM-dd) are both
 *  inclusive. No two periods of a sheet overlap. A closed period keeps `closedTotal`, the due-total fixed when it
 *  was closed; no claim dated inside it can be added, edited, opened, settled or voided. */
export type Period = {
  id: number;
  sheetId: string;
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'];

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
  });
}

/** The period whose dates contain a date (yyyy-MM-dd), or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return periods?.find((p) => p.from <= date && date <= p.to);
}
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's content on the home screen. Rendered once a user is signed in and a sheet is
 * loaded; everything a contribution shows or changes belongs to `sheetId` and is done as `user`.
 */
export const SheetPage = defineSlot<{ sheetId: string; user: string }>('sheet.page');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { createFileRoute } from '@tanstack/react-router';
