import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Person } from '../people/people';

/** A claim's status: DRAFT when added, then OPEN and SETTLED; a DRAFT or OPEN claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim of a person. `amount` is text with two decimals (never a float); `date` is yyyy-MM-dd; `number` is given
 *  when the claim is opened (null for a draft or a voided claim); `due` is the due fixed when it was settled (null
 *  while its due is live, worked out from its grade's current rate); `openedBy` is who opened it (null when never
 *  opened); `stated` is whether its person's last statement bound it to the figure `statedDue` (null when it had
 *  none), which it shows while its due is not fixed; `corrects` is, for a correction (a negative amount),
 *  the number of the SETTLED claim of the same person it corrects (null for any other claim). */
export type Claim = {
  id: number;
  sheetId: string;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: number | null;
};

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'];

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** An amount ("12.34") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether a claim counts toward claimed and the totals: only OPEN and SETTLED claims do. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** The claims that count in the live totals (claimed, due-totals, a period's due-total): a held person's OPEN claims
 *  do not; their SETTLED ones still do. */
export function live(claims: Claim[], people: Person[] | undefined): Claim[] {
  const held = new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId)));
}

/** The amounts of the claims that count added up, shown with two decimals. */
export function total(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts, type Claim } from '../claims/claims';
import { lateSteps, type Late } from '../overdue/late';
import { gradeOn, type Person } from '../people/people';

/** A grade's rate on the sheet: `rate` is a percent as text with two decimals (never a float), in force from
 *  `from` (yyyy-MM-dd; null: from the beginning of time). */
export type Rate = { sheetId: string; grade: string; rate: string; from: string | null };

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'];

/** The sheet's rates, by grade then from-date. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it, a rate
 *  with no from-date applying from the beginning of time; undefined when none applies. */
export function rateFor(rates: Rate[] | undefined, grade: string, on: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** A two-decimal number ("12.34") in hundredths, exactly. */
function hundredths(value: string): bigint {
  const t = value.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const h = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -h : h;
}

/** Hundredths shown with two decimals. */
function shown(h: bigint): string {
  const sign = h < 0n ? '-' : '';
  const a = h < 0n ? -h : h;
  return `${sign}${a / 100n}.${String(a % 100n).padStart(2, '0')}`;
}

/** What is due on an amount at a rate: amount × rate / 100, rounded half to even to two decimals, and at least
 *  the floor (two decimals) unless it is a correction (a negative amount); 'n/a' when there is no rate. */
export function due(amount: string, rate: string | undefined, floor: string): string {
  if (rate === undefined) return 'n/a';
  const d = percentOf(amount, rate, 1);
  const f = hundredths(floor);
  return shown(d < f && hundredths(amount) >= 0n ? f : d);
}

/** `times` × value × pct / 100 in hundredths, rounded half to even to two decimals. */
function percentOf(value: string, pct: string, times: number): bigint {
  const p = hundredths(value) * hundredths(pct) * BigInt(times); // in 1/10000 of a hundredth
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && q % 2n === 1n) ? q + 1n : q;
  return p < 0n ? -r : r;
}

/** A claim's due: the figure fixed when it was settled, otherwise the one its person's last statement bound it to,
 *  otherwise its amount at the rate in force on its date, at least the sheet's floor. Given the sheet's late
 *  charge, an overdue claim's figure gains the late percent of it for every full 30 days overdue (never bound by a
 *  statement; frozen in when settled). */
export function claimDue(claim: Claim, rate: string | undefined, floor: string, late?: Late): string {
  if (claim.due !== null) return claim.due;
  const figure = claim.stated ? (claim.statedDue ?? 'n/a') : due(claim.amount, rate, floor);
  if (late === undefined || figure === 'n/a') return figure;
  const steps = lateSteps(claim, late);
  return steps === 0 ? figure : shown(hundredths(figure) + percentOf(figure, late.pct, steps));
}

/** A person's due-total: the figures of their claims that count (each at the rate, of the grade in force, on its
 *  date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has a
 *  figure. */
